 848		private _installAgentRequestProjection(): void {
 849			const previousPrepareRequest = this.agent.prepareRequest;
 850			this.agent.prepareRequest = async (request, signal) => {
 851				const failed = this._failedResponse;
 852				this._failedResponse = undefined;
 853				const prepare = async () => {
 854					const projection = this.sessionManager.buildSessionProjection();
 855					const canonicalContext = {
 856						...request.context,
 857						messages: projection.messages,
 858						// Messages declare the provider-visible loadout; context.tools keeps executable implementations.
 859						tools: this.agent.state.tools.slice(),
 860					};
 861					const previous = await previousPrepareRequest?.(
 862						{
 863							...request,
 864							context: canonicalContext,
 865							model: this.agent.state.model,
 866							thinkingLevel: this.agent.state.thinkingLevel,
 867						},
 868						signal,
 869					);
 870					return { previous, context: previous?.context ?? canonicalContext, projection };
 871				};
 872				let { previous, context, projection } = await prepare();
 873				const model = previous?.model ?? this.agent.state.model;
 874				const thinkingLevel = previous?.thinkingLevel ?? this.agent.state.thinkingLevel;
 875				if (!isVirtualModel(model)) return { ...previous, context, model, thinkingLevel };
 876	
 877				// The selection stays in agent state; only this request uses the routed model. A routing
 878				// failure rejects, which ends the run with an error response. Only messages the user wrote
 879				// start a turn; extension messages can follow them, e.g. from before_agent_start.
 880				const lastResponse = context.messages.findLastIndex((message) => message.role === "assistant");
 881				const userTurn = context.messages.slice(lastResponse + 1).some((message) => message.role === "user");
 882				const state = getVirtualModelState(this.sessionManager.getBranch(), model.provider, model.id);
 883				const route = await this._modelRuntime.resolveModel(model, convertToLlm(context.messages), {
 884					reason: failed ? "retry" : userTurn ? "user" : "continuation",
 885					thinkingLevel,
 886					signal,
 887					failed,
 888					state,
 889				});
 890				if (route.state !== undefined && route.state !== state) {
 891					const data: VirtualModelStateData = { provider: model.provider, modelId: model.id, state: route.state };
 892					const entry = this.sessionManager.getEntry(
 893						this.sessionManager.appendCustomEntry(VIRTUAL_MODEL_STATE_ENTRY, data),
 894					);
 895					if (entry) this._emit({ type: "entry_appended", entry });
 896				}
