 898				// the projection.
 899				if (this._exceedsCompactionThreshold(route.model, projection)) {
 900					await this._runAutoCompaction("threshold", false);
 901					({ previous, context } = await prepare());
 902				}
 903				return { ...previous, context, model: route.model, thinkingLevel: route.thinkingLevel };
 904			};
