 855					const canonicalContext = {
 856						...request.context,
 857						messages: projection.messages,
 858						// Messages declare the provider-visible loadout; context.tools keeps executable implementations.
 859						tools: this.agent.state.tools.slice(),
 860					};
 861					const previous = await previousPrepareRequest?.(
 862						{
 863							...request,
 864							context: canonicalContext,
 865							model: this.agent.state.model,
 866							thinkingLevel: this.agent.state.thinkingLevel,
 867						},
 868						signal,
 869					);
 870					return { previous, context: previous?.context ?? canonicalContext, projection };
 871				};
