 878				// failure rejects, which ends the run with an error response. Only messages the user wrote
 879				// start a turn; extension messages can follow them, e.g. from before_agent_start.
 880				const lastResponse = context.messages.findLastIndex((message) => message.role === "assistant");
 881				const userTurn = context.messages.slice(lastResponse + 1).some((message) => message.role === "user");
 882				const state = getVirtualModelState(this.sessionManager.getBranch(), model.provider, model.id);
 883				const route = await this._modelRuntime.resolveModel(model, convertToLlm(context.messages), {
 884					reason: failed ? "retry" : userTurn ? "user" : "continuation",
 885					thinkingLevel,
 886					signal,
 887					failed,
 888					state,
 889				});
